-- Explicit portal v4 -> v5. No original sys schema changes.
CREATE TABLE cms_site(site_id BIGINT NOT NULL PRIMARY KEY,draft_json MEDIUMTEXT NOT NULL,published_release_id BIGINT NULL,version BIGINT NOT NULL DEFAULT 1,create_by VARCHAR(64) NOT NULL DEFAULT '',create_time DATETIME NOT NULL,update_by VARCHAR(64) NOT NULL DEFAULT '',update_time DATETIME NULL,remark VARCHAR(500) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cms_site_release(release_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,site_id BIGINT NOT NULL,config_json MEDIUMTEXT NOT NULL,theme_version VARCHAR(32) NOT NULL,create_by VARCHAR(64) NOT NULL DEFAULT '',create_time DATETIME NOT NULL,update_by VARCHAR(64) NOT NULL DEFAULT '',update_time DATETIME NULL,remark VARCHAR(500) NOT NULL DEFAULT '',UNIQUE KEY uk_site_release_owner(site_id,release_id),CONSTRAINT fk_site_release_site FOREIGN KEY(site_id) REFERENCES cms_site(site_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE cms_site ADD CONSTRAINT fk_site_current_release FOREIGN KEY(site_id,published_release_id) REFERENCES cms_site_release(site_id,release_id);
UPDATE cms_site SET published_release_id=LAST_INSERT_ID() WHERE site_id=1;
